  throw new Error("La altitud de crucero en pies es requerida.");
}
if (typeof args.altitud_destino_ft !== 'number' || !Number.isFinite(args.altitud_destino_ft)) {
  throw new Error("La altitud objetivo en pies es requerida.");
}
const altitud_a_perder = args.altitud_crucero_ft - args.altitud_destino_ft;
if (altitud_a_perder <= 0) {
  throw new Error("La altitud de crucero debe ser mayor que la altitud objetivo.");
}
const tod_nm = Math.round((altitud_a_perder / 1000) * 3 * 100) / 100;
return {
  distancia_tod_nm: tod_nm
};

